use proc_macro::TokenStream;
use quote::{format_ident,quote};
use syn::{parse::Parser,parse_macro_input,Data,DeriveInput,Fields,ItemFn,LitStr,ReturnType};
#[derive(Clone,Copy)]enum Kind{Component,Resource,Asset,Value}
impl Kind{fn parse(s:&str)->syn::Result<Self>{match s{"component"=>Ok(Self::Component),"resource"=>Ok(Self::Resource),"asset"=>Ok(Self::Asset),"value"=>Ok(Self::Value),_=>Err(syn::Error::new(proc_macro2::Span::call_site(),"kind must be component, resource, asset, or value"))}}}
#[derive(Default)]struct FieldFlags{read:bool,write:bool,persist:bool,skip:bool}
fn field_flags(attrs:&[syn::Attribute])->syn::Result<FieldFlags>{let mut f=FieldFlags::default();for a in attrs.iter().filter(|a|a.path().is_ident("trinity")){a.parse_nested_meta(|m|{if m.path.is_ident("read"){f.read=true}else if m.path.is_ident("write"){f.write=true}else if m.path.is_ident("persist"){f.persist=true}else if m.path.is_ident("skip"){f.skip=true}Ok(())})?;}Ok(f)}
fn docs(attrs:&[syn::Attribute])->String{attrs.iter().filter(|a|a.path().is_ident("doc")).filter_map(|a|match &a.meta{syn::Meta::NameValue(v)=>match &v.value{syn::Expr::Lit(e)=>match &e.lit{syn::Lit::Str(s)=>Some(s.value().trim().to_owned()),_=>None},_=>None},_=>None}).filter(|s|!s.is_empty()).collect::<Vec<_>>().join("\n")}
struct ClassArgs{module:String,name:Option<String>,legacy:String,kind:Kind}
fn class_args(input:&DeriveInput)->syn::Result<ClassArgs>{let mut out=ClassArgs{module:"trinity".into(),name:None,legacy:String::new(),kind:Kind::Component};for a in input.attrs.iter().filter(|a|a.path().is_ident("trinity")){a.parse_nested_meta(|m|{if m.path.is_ident("module"){out.module=m.value()?.parse::<LitStr>()?.value()}else if m.path.is_ident("name"){out.name=Some(m.value()?.parse::<LitStr>()?.value())}else if m.path.is_ident("legacy_header"){out.legacy=m.value()?.parse::<LitStr>()?.value()}else if m.path.is_ident("kind"){out.kind=Kind::parse(&m.value()?.parse::<LitStr>()?.value())?}Ok(())})?;}Ok(out)}
#[proc_macro_derive(TrinityClass,attributes(trinity))]pub fn derive_trinity_class(input:TokenStream)->TokenStream{let input=parse_macro_input!(input as DeriveInput);match expand_class(&input){Ok(t)=>t.into(),Err(e)=>e.into_compile_error().into()}}
fn expand_class(input:&DeriveInput)->syn::Result<proc_macro2::TokenStream>{let ident=&input.ident;let a=class_args(input)?;let module=LitStr::new(&a.module,ident.span());let owned=ident.to_string();let name=LitStr::new(a.name.as_deref().unwrap_or(&owned),ident.span());let rust=LitStr::new(&owned,ident.span());let legacy=LitStr::new(&a.legacy,ident.span());let doc=LitStr::new(&docs(&input.attrs),ident.span());let kind=match a.kind{Kind::Component=>quote!(::trinity_meta::TrinityClassKind::Component),Kind::Resource=>quote!(::trinity_meta::TrinityClassKind::Resource),Kind::Asset=>quote!(::trinity_meta::TrinityClassKind::Asset),Kind::Value=>quote!(::trinity_meta::TrinityClassKind::Value)};let fields=match &input.data{Data::Struct(d)=>match &d.fields{Fields::Named(fs)=>{let mut out=Vec::new();for f in &fs.named{let Some(id)=&f.ident else{continue};let flags=field_flags(&f.attrs)?;if flags.skip{continue}let n=LitStr::new(&id.to_string(),id.span());let r=flags.read;let w=flags.write;let p=flags.persist;out.push(quote!(::trinity_meta::TrinityFieldInfo::new(#n,#r,#w,#p)));}out},_=>Vec::new()},_=>return Err(syn::Error::new_spanned(input,"TrinityClass can only be derived for structs"))};Ok(quote!{impl ::trinity_meta::TrinityClass for #ident{const CARBON_MODULE:&'static str=#module;const CARBON_NAME:&'static str=#name;fn trinity_class_info()->::trinity_meta::TrinityClassInfo{::trinity_meta::TrinityClassInfo{module:#module.to_owned(),carbon_name:#name.to_owned(),rust_name:#rust.to_owned(),legacy_header:#legacy.to_owned(),doc:#doc.to_owned(),kind:#kind,fields:vec![#(#fields),*]}}}})}
struct TestArgs{legacy:String,verification:String}
fn parse_test_args(tokens:proc_macro2::TokenStream)->syn::Result<TestArgs>{let mut legacy=None;let mut verification="kani".to_owned();syn::meta::parser(|m|{if m.path.is_ident("legacy"){legacy=Some(m.value()?.parse::<LitStr>()?.value());Ok(())}else if m.path.is_ident("verification"){verification=m.value()?.parse::<LitStr>()?.value();Ok(())}else{Err(m.error("supported options: legacy, verification"))}}).parse2(tokens)?;Ok(TestArgs{legacy:legacy.ok_or_else(||syn::Error::new(proc_macro2::Span::call_site(),"legacy is required"))?,verification})}
#[proc_macro_attribute]pub fn trinity_test(attr:TokenStream,item:TokenStream)->TokenStream{let args=match parse_test_args(attr.into()){Ok(a)=>a,Err(e)=>return e.into_compile_error().into()};let f=parse_macro_input!(item as ItemFn);if !f.sig.inputs.is_empty()||!matches!(f.sig.output,ReturnType::Default){return syn::Error::new_spanned(&f.sig,"#[trinity_test] requires fn()").into_compile_error().into()}let attrs=&f.attrs;let vis=&f.vis;let name=&f.sig.ident;let body=format_ident!("__trinity_test_body_{name}");let desc=format_ident!("__TRINITY_TEST_{}",name.to_string().to_ascii_uppercase());let block=&f.block;let legacy=LitStr::new(&args.legacy,name.span());let rust=LitStr::new(&name.to_string(),name.span());let verification=match args.verification.as_str(){"kani"=>quote!(::trinity_meta::VerificationClass::Kani),"native"=>quote!(::trinity_meta::VerificationClass::Native),"render-device"=>quote!(::trinity_meta::VerificationClass::RenderDevice),"screenshot"=>quote!(::trinity_meta::VerificationClass::Screenshot),"integration"=>quote!(::trinity_meta::VerificationClass::Integration),_=>quote!(::trinity_meta::VerificationClass::Unmapped)};quote!{#(#attrs)* #[test] #vis fn #name(){#body();} #[doc(hidden)] pub fn #body() #block #[doc(hidden)] pub const #desc: ::trinity_meta::TrinityTestDescriptor=::trinity_meta::TrinityTestDescriptor::new(#legacy,#rust,#verification);}.into()}
